// Stage-B fixture: geometry/10_geometry_convex_hull
// Executes the grading oracle (correctConvexHull, baseline.hpp) on the prompt's
// worked example and prints the hull canonicalized the way cpu.cc::validate()
// compares it: sorted by (x asc, then y asc). Each Point prints as [x, y].
#include <cstdio>
#include <vector>
#include <algorithm>

// Definitions normally provided by cpu.cc / the driver environment:
struct Point {
    double x, y;
};
#ifndef NO_INLINE
#define NO_INLINE __attribute__((noinline))
#endif

#include "baseline.hpp"

int main() {
    // input: [{0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}]
    std::vector<Point> points = {
        {0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}
    };
    std::vector<Point> hull;
    correctConvexHull(points, hull);

    // Canonicalization mirroring cpu.cc::validate() (lines 98-103): the
    // validator sorts both candidate and oracle hulls by (x, then y) before
    // elementwise comparison, so vertex ordering is immaterial to grading.
    std::sort(hull.begin(), hull.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    printf("[");
    for (size_t i = 0; i < hull.size(); i++) {
        printf("%s[%.17g,%.17g]", (i ? "," : ""), hull[i].x, hull[i].y);
    }
    printf("]\n");
    return 0;
}

